        br_navigation_mode=mode;
        for(unsigned side=0;side<2;side++) {
            if(br_sides[side].armed)br_schedule_locked(side); /* cancel old confirmation */
            for(unsigned i=0;i<2;i++)if(br_sides[side].key[i].down)br_sides[side].key[i].latched=1;
            if(br_sides[side].wheel.down)br_sides[side].wheel.latched=1;
        }
